import { html , render , WebComponent , customElement , attr , attrState , state, css, ViewTemplate, ViewContext, asyncAppend, repeat, children } from '@lithium-framework/core';
import '@lithium-framework/router-element';
import 'unofficial-pf-v5-wc';
import 'unofficial-pf-v5-wc-icons';
import '../../components';

@customElement({
  name: 'page-compte',
  template: html`${(compte: Compte) => {
    return html`
      <pf-page masterhead-no-icon masterhead-no-branding drawer-inline drawer-expanded drawer-static drawer-panel-left>
          <div slot = "drawer-panel">
            <navigation-panel></navigation-panel>
          </div>
          <pf-panel header scrollable>
            <div slot="header">
              <h1 class="title">Compte</h1>
            </div>
            <div class="table-infos">
              ${asyncAppend(compte.preloadData('http://localhost:3000/informations'), (result) => {
                  return html`${
                    repeat(
                      result,
                      html`${(info) => {
                        console.log(info)
                        return html`
                          <div class="row">
                            <div class="date-of-birth">
                              <label for="date_of_birth">Date de naissance:</label>
                              <input type="text" id="date_of_birth" value="${compte.formatDateFromISO(info.date_of_birth)}" readonly disabled/>
                            </div>

                            <div class="email">
                              <label for="email">Email:</label>
                              <input type="email" id="email" value="${info.email}" readonly/>
                            </div>

                            <div class="first-name">
                              <label for="first_name">Prénom:</label>
                              <input type="text" id="first_name" value="${info.first_name}" readonly/>
                            </div>

                            <div class="gender">
                              <label for="gender">Genre:</label>
                              <input type="text" id="gender" value="${info.gender}" readonly/>
                            </div>

                            <div class="dropdown">
                                <details>
                                <summary id="dropdownButtonGrade">${info.grade}</summary>
                                <div class="dropdown-menu" id="dropdownMenu">
                                  <!-- Les éléments du menu seront ajoutés ici -->
                                  ${asyncAppend(compte.preloadDataDropDown(`http://localhost:3000/informations/grade`), (result) => {
                                    console.log(result)
                                    return html`${repeat(
                                      result,
                                      html`${(grade) => {
                                        console.log(grade)
                                        return html`<div class="dropdown-item" data-grade="${grade.grade}"@click="${(grade) => compte.handleDropDownValueGrade(grade)}">
                                         ${grade.grade}
                                        </div>`;
                                      }}`
                                    )}`;
                                  })}
                                </div>
                              </details>
                            </div>

                            <div class="last-name">
                              <label for="last_name">Nom:</label>
                              <input type="text" id="last_name" value="${info.last_name}" readonly/>
                            </div>

                            <div class="role">
                              <label for="role">Rôle:</label>
                              <input type="text" id="role" value="${info.role}" readonly disabled/>
                            </div>

                            <div class="dropdown">
                                <details>
                                <summary id="dropdownButtonPrice">${info.abonnement}</summary>
                                <div class="dropdown-menu" id="dropdownMenu">
                                  <!-- Les éléments du menu seront ajoutés ici -->
                                  ${asyncAppend(compte.preloadDataDropDown(`http://localhost:3000/informations/abonnement`), (result) => {
                                    return html`${repeat(
                                      result,
                                      html`${(plan) => {
                                        console.log(plan.nom_plan)
                                        return html`<div class="dropdown-item" data-plan="${plan.nom_plan}" data-prix="${plan.prix}" @click="${(plan) => compte.handleDropDownValueTarif(plan)}">
                                         ${plan.nom_plan} - ${plan.prix} €
                                        </div>`;
                                      }}`
                                    )}`;
                                  })}
                                </div>
                              </details>
                            </div>
                            <!-- Bouton pour activer la modification -->
                             <button id="edit-button" @click="${() => compte.enableEditing(compte)}">Modifier</button>

                            <!-- Bouton pour enregistrer les modifications -->
                            <button id="save-button" style="display:none;" onclick="saveChanges()">Enregistrer</button>
                          </div>
                          `;
                      }}`
                    )
                  }`
                })
              }
            </div>
          </pf-panel>
        <pf-avatar></pf-avatar>
      </pf-page>`;
  }}`,
  styles : [
    css`
      .table-infos {
        color: black;
      }
      .navigation{
        color: black
      }
      .title{
        color: black;
      }
       /* Conteneur du dropdown */
.dropdown {
  position: relative;
  display: inline-block;
  width: 100%;
}

/* Bouton du dropdown */
.dropdown-toggle {
      background-color: #fafbfe;
  color: #a2adcd;
  padding: 10px 20px;
  font-size: 16px;
  border: none;
  cursor: pointer;
  border-radius: 4px;
  width: 100%;
}

/* Liste cachée par défaut */
.dropdown-menu {
  display: none;
  position: absolute;
  background-color: #f9f9f9;
  min-width: 160px;
  box-shadow: 0px 8px 16px rgba(0, 0, 0, 0.2);
  z-index: 1;
  border-radius: 4px;
  overflow: hidden;
  width: 100%;
}

/* Eléments du dropdown */
.dropdown-item {
  padding: 12px 16px;
  text-align: left;
  color: black;
  text-decoration: none;
  display: block;
  font-size: 14px;
}

/* Changer la couleur au survol */
.dropdown-item:hover {
  background-color: #f1f1f1;
  cursor: pointer;
}

/* Affichage du menu lorsque l'utilisateur clique sur le bouton */
.dropdown:hover .dropdown-menu {
  display: block;
}

#dropdownMenu {
  display: none;
  /* Autres styles pour le menu */
}

#dropdownMenu.visible {
  display: block;
  /* Autres styles pour le menu visible, comme une animation */
}

    `
  ]
})

export class Compte extends WebComponent {
  data: any[] = [];

  tarif: string = '';
  grade: string = '';


  async preloadData(url): Promise<any[]> {
    try {
      const userDataString = localStorage.getItem('userData');
      if (!userDataString) {
        throw new Error('Utilisateur non connecté. Aucune donnée dans localStorage.');
      }
  
      const userData = JSON.parse(userDataString);
      console.log('Données utilisateur récupérées:', userData);
  
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(userData),
      });
  
      if (!response.ok) {
        throw new Error('Erreur serveur.');
      }
  
      const data = await response.json();
  
      // Enveloppe l'objet dans un tableau
      const dataArray = [data]; // Si `data` est un objet, on le met directement dans un tableau
  
      console.log('Données mises dans un tableau:', dataArray, dataArray.length);
  
      return dataArray.length > 0 ? dataArray : []; // Retourne le tableau, ou un tableau vide si aucun élément
    } catch (error) {
      console.error('Erreur lors de la requête fetch:', error);
      return [];
    }
  }

  handleDropDownValueGrade(grade) {
    const dropdownButton = this.shadowRoot?.getElementById('dropdownButtonPrice');
    const dropdownMenu = this.shadowRoot?.getElementById('dropdownMenu');

    
    // Mettre à jour le texte du bouton avec la sélection
    dropdownButton.textContent = `${grade.grade}`;
    this.grade = grade.grade;
    console.log(this.grade)
    
    // Vérifier si le menu est déjà ouvert ou non et ajuster son état
    if (dropdownMenu.style.display === 'none') {
      // Ouvrir le menu si il est fermé (display: none ou initialement vide)
      dropdownMenu.style.display = 'block';
    } else {
      // Fermer le menu si il est déjà ouvert
      dropdownMenu.style.display = 'none';
    }
  }




  handleDropDownValueTarif(plan) {
    // Sélectionner les éléments dans le Shadow DOM
    const dropdownButton = this.shadowRoot?.getElementById('dropdownButtonPrice');
    const dropdownMenu = this.shadowRoot?.getElementById('dropdownMenu');

    console.log(dropdownMenu, dropdownButton)
    
    // Mettre à jour le texte du bouton avec la sélection
    dropdownButton.textContent = `${plan.nom_plan} - ${plan.prix} €`;
    this.tarif = plan.nom_plan;
    console.log(this.tarif)
    
    // Vérifier si le menu est déjà ouvert ou non et ajuster son état
    if (dropdownMenu.style.display === 'none') {
      // Ouvrir le menu si il est fermé (display: none ou initialement vide)
      dropdownMenu.style.display = 'block';
    } else {
      // Fermer le menu si il est déjà ouvert
      dropdownMenu.style.display = 'none';
    }
  }

  async preloadDataDropDown(url): Promise<any[]> {
    try {
  
      const response = await fetch(url, {
        method: 'GET',
        credentials: 'include', // Inclure les cookies et autres credentials si nécessaire
        headers: {
          'Content-Type': 'application/json',
        },
      });
  
      if (!response.ok) {
        throw new Error('Erreur serveur.');
      }
  
      const data = await response.json();
  
      console.log(data, data.length);
  
      return data.length > 0 ? data : []; // Retourne le tableau, ou un tableau vide si aucun élément
    } catch (error) {
      console.error('Erreur lors de la requête fetch:', error);
      return [];
    }
  }

  enableEditing(compte) {
    console.log("enable editing")
    // Accéder au Shadow DOM avec `this.shadowRoot`
    this.shadowRoot.getElementById('first_name').removeAttribute('readonly');
    this.shadowRoot.getElementById('last_name').removeAttribute('readonly');
    this.shadowRoot.getElementById('grade').removeAttribute('readonly');
    this.shadowRoot.getElementById('email').removeAttribute('readonly');
    this.shadowRoot.getElementById('edit-button').style.display = 'none';
    this.shadowRoot.getElementById('save-button').style.display = 'inline-block';
  
    // Retourner un message d'information
    return html`<div>Vous pouvez modifier désormais</div>`;
  }
  
  

  validateForm() {
    let email = document.getElementById('email').value;
    let regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!regex.test(email)) {
      alert('Veuillez entrer un email valide');
      return false;
    }
    return true;
  }

  saveChanges() {
    if (!this.validateForm()) return;
  
    let data = {
      email: document.getElementById('email').value,
      first_name: document.getElementById('first_name').value
      // Ajoute d'autres champs si nécessaire
    };
  
    fetch('/api/update-profile', {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(data)
    })
    .then(response => response.json())
    .then(result => {
      if (result.success) {
        alert('Modifications enregistrées avec succès');
      } else {
        alert('Erreur lors de l\'enregistrement');
      }
    })
    .catch(error => console.error('Erreur:', error));
  }
  

  formatDateFromISO(isoDateString: string): string {
    const date = new Date(isoDateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  convertToISODate(dateString: string): string {
    const [year, month, day] = dateString.split('-');
    return new Date(`${year}-${month}-${day}T00:00:00Z`).toISOString();
  }
  
}



let template: ViewTemplate<any> = html`${( context:ViewContext )=>{


  return html`<page-compte></page-compte>`;

}}`




render(template);